{"content":""""summarize_jsonl: resume un iterable de lineas JSONL (validacion estricta).

Ignora lineas vacias o de solo espacios. Cada linea no vacia debe ser un objeto
JSON con id, level y duration_ms de tipos correctos; una linea con JSON valido
pero tipos incorrectos es invalida completa y no suma.

Devuelve:
  count, by_level (alfabetico), total_duration_ms,
  p95_duration_ms (nearest-rank sobre duraciones validas ordenadas),
  invalid_lines.
No muta la entrada y mantiene enteros cuando corresponde.
"""

import json
import math


def _valid_entry(record):
    """Devuelve (id, level, duration_ms) si es valido; None si no lo es."""
    if not isinstance(record, dict):
        return None

    if "id" not in record or "level" not in record or "duration_ms" not in record:
        return None

    entry_id = record["id"]
    level = record["level"]
    duration = record["duration_ms"]

    if not isinstance(entry_id, str) or entry_id == "":
        return None
    if not isinstance(level, str) or level == "":
        return None
    if isinstance(duration, bool) or not isinstance(duration, int):
        return None

    return entry_id, level, duration


def summarize_jsonl(lines):
    if isinstance(lines, (str, bytes)):
        raise ValueError("lines debe ser un iterable de lineas, no un string")

    count = 0
    invalid_lines = 0
    level_counts = {}
    total_duration_ms = 0
    durations = []

    for line in lines:
        if isinstance(line, bytes):
            try:
                line = line.decode("utf-8")
            except UnicodeDecodeError:
                invalid_lines += 1
                continue
        if not isinstance(line, str):
            invalid_lines += 1
            continue

        if line.strip() == "":
            continue

        try:
            record = json.loads(line)
        except ValueError:
            invalid_lines += 1
            continue

        entry = _valid_entry(record)
        if entry is None:
            invalid_lines += 1
            continue

        _, level, duration = entry
        count += 1
        level_counts[level] = level_counts.get(level, 0) + 1
        total_duration_ms += duration
        durations.append(duration)

    durations.sort()
    if durations:
        rank = math.ceil(0.95 * len(durations))
        p95 = durations[rank - 1]
    else:
        p95 = 0

    return {
        "count": count,
        "by_level": {level: level_counts[level] for level in sorted(level_counts)},
        "total_duration_ms": total_duration_ms,
        "p95_duration_ms": p95,
        "invalid_lines": invalid_lines,
    }
